/**
 * src/modules/voice-core/api/elevenlabs/tts.ts
 * ─────────────────────────────────────────────────────────────────────────────
 * POST /api/voice/elevenlabs/tts — streaming text-to-speech (Mode A speech-out).
 *
 * The ONLY data that crosses the ElevenLabs boundary here is the answer text
 * to be spoken (already generated by the platform's own chat + RAG).
 * The response audio streams straight through — never buffered whole.
 *
 * Guards: ELEVENLABS_TTS_RATE (60/min/org — parity with CHAT_RATE) + the
 * 2,000-character per-request cap + server-side re-resolution.
 */

import { NextRequest, NextResponse } from "next/server";
import { ensureMigrated } from "@/lib/db/migrate";
import { query as dbQuery } from "@/lib/db";
import { planGuard } from "@/lib/plan-guard";
import { hit, rateLimitResponse, ELEVENLABS_TTS_RATE, ELEVENLABS_PREVIEW_RATE } from "@/lib/rate-limit";
import {
  TTS_MAX_CHARS_PER_REQUEST,
  TTS_OUTPUT_FORMAT,
  TTS_PREVIEW_MAX_CHARS,
  isSupportedTTSModel,
  isValidUuid,
  looksLikeElevenLabsVoiceId,
} from "../../model-catalog";
import { VoiceProviderFactory } from "../../factory";
import { ElevenLabsError } from "../../providers/elevenlabs";
import { logTtsUsage } from "../../metering";
import { VoiceConfigResolutionError, resolveVoiceConfigCached } from "../../resolve";
import { sanitizeTtsText } from "../../tts-text";
import { embedVoiceGuard } from "./embed-auth";

export async function postElevenLabsTts(request: NextRequest): Promise<NextResponse | Response> {
  try {
    await ensureMigrated();

    const body = await request.json().catch(() => null) as Record<string, unknown> | null;
    if (!body) {
      return NextResponse.json({ error: "JSON body required." }, { status: 400 });
    }

    const kbId = typeof body.kbId === "string" ? body.kbId.trim() : null;
    const surface = body.surface === "voice_chat" ? "voice_chat" : "realtime";
    const text = typeof body.text === "string" ? body.text : "";
    const preview = body.preview === true;

    if (!text.trim()) {
      return NextResponse.json({ error: "text is required." }, { status: 400 });
    }

    // RAG answers carry markdown + [S1]-style citation tags meant for the
    // eye, not the ear (production HAR showed "[S2]" dispatched as its own
    // TTS call). Strip BEFORE the caps check, BEFORE metering, BEFORE the
    // vendor call — metering then reflects exactly what was spoken.
    const speakableText = sanitizeTtsText(text);
    if (!speakableText) {
      return NextResponse.json(
        { error: "text contains nothing speakable after removing citations and markdown." },
        { status: 400 },
      );
    }

    const maxChars = preview ? TTS_PREVIEW_MAX_CHARS : TTS_MAX_CHARS_PER_REQUEST;
    if (speakableText.length > maxChars) {
      return NextResponse.json(
        { error: `Text too long (${speakableText.length} chars). Maximum is ${maxChars} per request.` },
        { status: 413 },
      );
    }

    if (!kbId || !isValidUuid(kbId)) {
      return NextResponse.json({ error: "A valid kbId is required." }, { status: 400 });
    }

    // Embed-authenticated callers (clr_ API key from the public voice
    // surfaces): validate the key/KB pairing. No hourly-increment — this
    // route fires per sentence and the dedicated TTS bucket already
    // throttles per org (see embed-auth.ts for the rationale).
    const embedDenied = await embedVoiceGuard(request, kbId);
    if (embedDenied) return embedDenied;

    const orgRows = await dbQuery<{ org_id: string; agent_id: string }>(
      `SELECT a.org_id, a.id AS agent_id FROM agents a JOIN knowledge_bases kb ON kb.agent_id = a.id WHERE kb.id = $1`,
      [kbId],
    );
    const orgId = orgRows[0]?.org_id ?? null;
    const agentId = orgRows[0]?.agent_id ?? null;

    {
      const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim()
        ?? request.headers.get("x-real-ip") ?? "unknown";
      const bucket = preview ? "el-tts-preview" : "el-tts";
      const rate = preview ? ELEVENLABS_PREVIEW_RATE : ELEVENLABS_TTS_RATE;
      const gate = hit(
        `${bucket}:${orgId ? `org:${orgId}` : `ip:${ip}`}`,
        rate.limit,
        rate.windowMs,
      );
      if (!gate.allowed) {
        const rl = rateLimitResponse(gate.retryAfterSec, "Text-to-speech rate limit reached. Please slow down.");
        return NextResponse.json(rl.body, { status: rl.status, headers: rl.headers });
      }
    }

    if (orgId) {
      // Rolling-24 h voice budget (dormant until operators set plan values).
      const ttsGuard = await planGuard(orgId, "tts");
      if (!ttsGuard.allowed) {
        const blocked = ttsGuard as { reason: string };
        return NextResponse.json(
          { error: "plan_limit_exceeded", code: "tts_limit_reached", message: blocked.reason },
          { status: 402 },
        );
      }
    }

    // Server-side re-resolution: client-suggested voice/model are advisory.
    // Cached for 5 s — this route fires per sentence, and the resolution walk
    // (~8 DB round trips) otherwise dominates the latency budget of every
    // short-sentence call (see ELEVENLABS_REALTIME_STREAMING_PLAN.md).
    // Realtime axis to match the session bootstrap (see session.ts).
        // scope:"draft" — the authenticated agent preview resolves against
    // the CURRENT Main-branch draft instead of the immutable published
    // version (KB overrides apply; the LIVE collection is searched).
    const resolved = await resolveVoiceConfigCached({ kbId, surface, ...(body?.scope === "draft" ? { preferDraft: true } : {}) });
    // Either voice purpose selects the pipeline (voice-chat axis, or the
    // realtime axis using Mode A as its fallback / embed transport).
    const selectedProvider =
      surface === "voice_chat" ? resolved.voiceProvider : resolved.realtimeProvider;
    if (selectedProvider !== "elevenlabs" || !resolved.elevenlabs) {
      return NextResponse.json(
        { error: "Voice provider is not ElevenLabs for this knowledge base.", provider: resolved.realtimeProvider },
        { status: 409 },
      );
    }

    const model = typeof body.model === "string" && isSupportedTTSModel(body.model)
      ? body.model
      : resolved.elevenlabs.ttsModel;
    const voiceId = typeof body.voiceId === "string" && looksLikeElevenLabsVoiceId(body.voiceId)
      ? body.voiceId
      : resolved.elevenlabs.voiceId;
    const language = typeof body.language === "string" ? body.language : resolved.elevenlabs.language;

    const voiceService = VoiceProviderFactory.getVoiceService();

    const startedAt = Date.now();
    const audioResponse = await voiceService.speak({
      text: speakableText,
      voiceId,
      modelId: model,
      outputFormat: TTS_OUTPUT_FORMAT,
      languageCode: language ?? null,
      ...(body.voiceSettings && typeof body.voiceSettings === "object"
        ? (body.voiceSettings as Record<string, number>)
        : {}),
    });
    const latencyMs = Date.now() - startedAt;

    // Meter from the request fact (character count of what was actually
    // spoken) — cheap and exact.
    await logTtsUsage({
      orgId,
      kbId,
      agentId,
      model,
      latencyMs,
      characters: speakableText.length,
      preview,
    });

    // Stream the raw audio through without buffering (PCM16 mono 16 kHz by
    // default; format string passed straight to the vendor).
    return new Response(audioResponse.body, {
      status: 200,
      headers: {
        "Content-Type": TTS_OUTPUT_FORMAT.startsWith("pcm")
          ? "application/octet-stream"
          : "audio/mpeg",
        "Cache-Control": "no-store",
        "X-ElevenLabs-Model": model,
        "X-ElevenLabs-Voice": voiceId,
      },
    });
  } catch (error) {
    console.error("[elevenlabs-tts] post:", error);
    if (error instanceof ElevenLabsError) {
      return NextResponse.json({ error: error.message }, { status: 502 });
    }
    if (error instanceof VoiceConfigResolutionError) {
      return NextResponse.json({ error: error.message }, { status: 400 });
    }
    return NextResponse.json({ error: (error as Error).message }, { status: 500 });
  }
}
